#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line); // Read the first line and ignore
    getline(cin, line); // Read the second line

    // Split the line by parentheses pattern
    vector<string> parts;
    size_t start = 0;
    for (size_t i = 0; i < line.size(); ++i) {
        if (line[i] == '(') {
            parts.push_back(line.substr(start, i - start));
            start = i + 1;
        } else if (line[i] == ')') {
            parts.push_back(line.substr(start, i - start));
            start = i + 1;
        }
    }
    if (start < line.size()) {
        parts.push_back(line.substr(start));
    }

    int maxLength = 0;
    for (const auto& part : parts) {
        // Split by underscores
        stringstream ss(part);
        string segment;
        while (getline(ss, segment, '_')) {
            maxLength = max(maxLength, (int)segment.length());
        }
    }

    int count = 0;
    int parenthesesCount = 0;
    bool insideParentheses = false;
    bool counted = false;

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (c == '(') {
            insideParentheses = true;
        } else if (c == ')') {
            counted = false;
            insideParentheses = false;
        } else if (insideParentheses && isalpha(c)) {
            if (counted) continue;
            parenthesesCount++;
            counted = true;
        } else if (c == '_') {
            counted = false;
        }
    }

    cout << maxLength << " " << parenthesesCount << "\n";

    return 0;
}
